<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useOrganizationStore } from '@/stores/organization'
import { createPrivateAsset, uploadPrivateAsset, createSalesRecording, submitSalesTranscription, getAsyncTask, retryAsyncTask, deleteSalesRecording, createSalesAnalysis, getSalesAnalysis, listSalesRecordings, saveSalesTranscript, updateTrainingTask } from '@/api/growth'
const organization=useOrganizationStore(), recordings=ref([]), current=ref(null), analysis=ref(null), file=ref(null)
const sellerLabel=ref('销售A'), scene=ref('new_sale'), consent=ref(false), transcript=ref(''), busy=ref(false), loading=ref(true), error=ref(''), message=ref(''), task=ref(null), stage=ref('idle'); let timer
const config=()=>({headers:organization.headers()}); const terminal=new Set(['succeeded','failed_retryable','failed_final','needs_review','cancelled'])
async function load(){loading.value=true;error.value='';try{await organization.load();const r=await listSalesRecordings(config());recordings.value=(r.recordings||[]).filter(i=>i.status!=='deleted');current.value=recordings.value[0]||null}catch(e){error.value='录音历史加载失败，请重试'}finally{loading.value=false}}
function chooseFile(e){const picked=e.target.files?.[0];error.value='';if(!picked)return;if(!picked.type.startsWith('audio/'))return error.value='请选择音频文件';if(picked.size>100*1024*1024)return error.value='音频不能超过100MB';file.value=picked}
async function upload(){if(!consent.value)return error.value='请先确认已获得录音授权';if(!sellerLabel.value.trim())return error.value='请填写沟通人员代称';if(!file.value)return error.value='请选择音频文件';busy.value=true;error.value='';try{stage.value='uploading';const meta=await createPrivateAsset({filename:file.value.name,mimeType:file.value.type,size:file.value.size,purpose:'sales_recording'},config());await uploadPrivateAsset(meta.asset.id,file.value,config());const created=await createSalesRecording({sellerLabel:sellerLabel.value.trim(),scene:scene.value,consentConfirmed:true,assetId:meta.asset.id},config());current.value=created.recording;recordings.value.unshift(created.recording);stage.value='queued';const submitted=await submitSalesTranscription(created.recording.id,config());task.value=submitted.task;message.value='音频已安全上传，正在整理沟通内容';poll()}catch(e){error.value='上传失败，请检查音频后重试';stage.value='failed'}finally{busy.value=false}}
async function poll(){clearTimeout(timer);if(!task.value)return;try{const r=await getAsyncTask(task.value.id,config());task.value=r.task;stage.value=r.task.status;if(!terminal.has(r.task.status))timer=setTimeout(poll,2000);else if(r.task.status==='succeeded')message.value='转写完成，可生成复盘报告';else if(r.task.status==='needs_review')message.value='自动转写需要人工复核，可使用手工填写沟通内容'}catch(e){error.value='内容整理暂未完成，请重试或填写手工文本';stage.value='failed_retryable'}}
async function retry(){busy.value=true;error.value='';try{const r=await retryAsyncTask(task.value.id,config());task.value=r.task;stage.value=r.task.status;poll()}catch(e){error.value='操作失败，请稍后重试'}finally{busy.value=false}}
async function analyse(){if(!current.value)return error.value='请先上传或选择录音';busy.value=true;error.value='';try{if(transcript.value.trim())await saveSalesTranscript(current.value.id,transcript.value,config());const r=await createSalesAnalysis(current.value.id,{confirmedScene:scene.value},config());analysis.value=(await getSalesAnalysis(r.analysis.id,config())).analysis;message.value='结构化复盘已完成'}catch(e){error.value='复盘生成失败，请填写手工文本后重试'}finally{busy.value=false}}
async function remove(item){if(!confirm('确认删除原音和录音入口？该操作不可撤销。'))return;busy.value=true;try{await deleteSalesRecording(item.id,config());recordings.value=recordings.value.filter(i=>i.id!==item.id);if(current.value?.id===item.id){current.value=recordings.value[0]||null;analysis.value=null}message.value='原音已删除'}catch(e){error.value='操作失败，请稍后重试'}finally{busy.value=false}}
async function completeTask(item){const r=await updateTrainingTask(item.id,'completed',config());item.status=r.task.status}
function select(item){current.value=item;analysis.value=null;task.value=null;stage.value='idle';transcript.value=''}
onMounted(load);onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><main class="page"><header><div><span class="eyebrow">家长沟通记录</span><h1>家长沟通复盘</h1><p>用于复盘新家长报名沟通和在读家长续费沟通；录音仅在获得授权后用于机构内部。</p></div></header><section v-if="loading" class="state">正在加载录音历史…</section><section v-else-if="error&&!recordings.length&&stage==='idle'" class="state error">{{error}}<button @click="load">重试</button></section><div v-else class="layout"><aside><h2>录音历史</h2><div v-if="!recordings.length" class="empty">暂无录音</div><div v-for="r in recordings" :key="r.id" class="record" :class="{active:current?.id===r.id}"><button @click="select(r)"><b>{{r.seller_label}}</b><small>{{r.scene==='renewal'?'续费':'新签'}} · #{{r.id}}</small></button><button class="delete" @click="remove(r)" aria-label="删除录音">删除</button></div></aside><section class="main"><article class="card"><h2>上传沟通录音</h2><div class="form"><label>沟通人员代称<input v-model="sellerLabel" maxlength="40" placeholder="如：顾问A（不要填写家长或儿童姓名）"></label><label>沟通场景<select v-model="scene"><option value="new_sale">新家长报名沟通</option><option value="renewal">在读家长续费沟通</option></select></label><label class="file">选择音频<input type="file" accept="audio/*" @change="chooseFile"><span>{{file?.name||'MP3 / M4A / WAV，最大100MB'}}</span></label><label class="consent"><input v-model="consent" type="checkbox"> 我确认已获得对话参与者授权，仅用于机构内部训练</label><button class="primary" @click="upload" :disabled="busy">{{stage==='uploading'?'正在上传…':'上传并整理内容'}}</button></div></article><article class="card progress"><h2>任务进度</h2><div class="steps"><span :class="{done:current}">1 私有上传</span><span :class="{done:['queued','processing','succeeded','needs_review'].includes(stage)}">2 整理内容</span><span :class="{done:stage==='succeeded'}">3 生成复盘</span></div><p v-if="stage==='idle'">选择历史录音，或上传新音频开始。</p><p v-else-if="['queued','processing'].includes(stage)" aria-live="polite">任务{{stage==='queued'?'排队中':'处理中'}}，页面将自动刷新状态…</p><div v-else-if="['failed_retryable','failed_final','failed'].includes(stage)" class="error">转写失败。<button v-if="stage==='failed_retryable'&&task" @click="retry">重新整理</button><span>也可在下方填写手工填写沟通内容。</span></div><p v-else-if="stage==='needs_review'">自动结果需复核，请填写手工文本后生成报告。</p><p v-else-if="stage==='succeeded'">沟通内容已整理，可直接生成复盘；如文字不完整，请补充手工文本。</p></article><article class="card report"><h2>沟通内容与复盘</h2><textarea v-model="transcript" rows="7" placeholder="可选：粘贴已脱敏的沟通文字作为补充。请勿包含家长手机号、儿童姓名。"></textarea><button class="primary" :disabled="busy||!current" @click="analyse">保存文本并生成复盘</button><template v-if="analysis"><div class="score">{{analysis.score??'—'}}<small>分 · {{analysis.level}}</small></div><p>{{analysis.report?.conclusion}}</p><div class="dimensions"><div v-for="d in analysis.report?.dimensions" :key="d.dimension"><b>{{d.label}}</b><strong>{{d.score}}/{{d.weight}}</strong><small>{{d.reason}}</small></div></div><h3>后续练习</h3><button v-for="t in analysis.trainingTasks" :key="t.id" class="task" @click="completeTask(t)" :disabled="t.status==='completed'">{{t.title}} <b>{{t.status==='completed'?'已完成':'标记完成'}}</b></button></template></article><div v-if="error" class="inline-error" role="alert">{{error}}</div><p v-if="message" class="message">{{message}}</p></section></div></main></template>
<style scoped>.page{min-height:100vh;padding:36px clamp(16px,4vw,56px);background:#f5f3ec;color:#17231c}.page>header,.layout,.state{max-width:1320px;margin:auto}.eyebrow{color:#8b681e;font-size:11px;font-weight:800}.page h1{margin:8px 0}.page p{color:#68756d;line-height:1.6}.layout{margin-top:24px;display:grid;grid-template-columns:230px 1fr;gap:18px}aside,.card{background:#fff;border:1px solid #dce2dc;border-radius:14px;padding:18px}aside h2,.card h2{font-size:17px;margin-bottom:14px}.record{display:flex;border-bottom:1px solid #e6e9e5}.record>button:first-child{flex:1;min-height:58px;text-align:left;padding:8px}.record b,.record small{display:block}.record small{color:#748078;margin-top:4px}.record.active{background:#e6f0e8}.delete{min-width:44px;color:#a13b32}.main{display:grid;gap:14px}.form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form label{font-size:12px;color:#69746d}.form input:not([type=checkbox]),.form select,.report textarea{display:block;width:100%;min-height:44px;margin-top:6px;border:1px solid #ccd5ce;border-radius:9px;padding:10px;background:#fff}.file{grid-column:1/-1}.file input{padding:8px}.file span{display:block;margin-top:5px}.consent{grid-column:1/-1;display:flex;align-items:center;gap:9px;min-height:44px}.consent input{width:20px;height:20px}.primary,.progress button{min-height:44px;padding:0 16px;border-radius:9px;background:#1e563a;color:#fff;font-weight:700}.steps{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.steps span{padding:8px 12px;border-radius:99px;background:#edf0ed;color:#68756d}.steps .done{background:#dcecdf;color:#174c30}.error,.inline-error{color:#9c3029}.error span{display:block;margin-top:8px}.report textarea{resize:vertical}.score{font-size:42px;color:#1e563a;font-weight:800;margin-top:20px}.score small{font-size:14px}.dimensions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0}.dimensions div{border:1px solid #e3e8e4;border-radius:10px;padding:12px}.dimensions strong,.dimensions small{display:block;margin-top:5px}.dimensions small{color:#69746d}.task{width:100%;min-height:44px;text-align:left;border-bottom:1px solid #e5e9e6;display:flex;justify-content:space-between}.task b{color:#1e563a}.state{margin-top:24px;padding:24px;background:#fff;border-radius:14px}.state button{min-height:44px;margin-left:10px}.inline-error{padding:12px;background:#fff0ef;border-radius:9px}@media(max-width:1000px) and (orientation:landscape){.layout{grid-template-columns:72px 1fr}aside{padding:8px}aside h2,.record small,.delete{display:none}.record b{font-size:0}.record b::first-letter{font-size:18px}}@media(max-width:760px),(orientation:portrait) and (max-width:1000px){.layout{grid-template-columns:1fr}.form,.dimensions{grid-template-columns:1fr}.file,.consent{grid-column:auto}.primary{width:100%}}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #dcae53;outline-offset:2px}</style>
